import { makeStyles } from '@rbx/ui';
import React from 'react';
import domPurify from 'dompurify';
import { textTruncationStylesWithWrap } from '../common/constants/styleConstants.js';
import { getTextStyles, defaultTextDataAttributeConfig, getTextDataAttribute } from '../common/utils/textStyleUtils.js';

const DOM_PURIFY_CONFIG = {
    ALLOWED_TAGS: ['em', 'i', 'strong', 'b', 'u', 'a', 'br'],
    ALLOWED_ATTR: ['href', 'target', 'rel']
};
const useStyles = makeStyles()((_theme, { textFontStyle, textColor }) => ({
    textClassName: {
        ...textTruncationStylesWithWrap,
        ...getTextStyles(defaultTextDataAttributeConfig, textColor, textFontStyle)
    }
}));
/**
 * WebText component displays a block of text.
 *
 * @component
 * @param {string} text - The text to be displayed.
 * @param {TTypographyToken} textFontStyle - The font style of the text.
 * @param {string} textColor - The color of the text to be displayed.
 * @param {TWebTextElement} webTextElement - The element to be used for the text, defaults to span if not provided.
 *
 * @example
 * <WebText
 *   text="Sample Text. Here is some nice text!<br />More text"
 *   textFontStyle={{
 *     Font: '700 14/1.2 "Builder Sans"',
 *     LetterSpacing: -0.01,
 *     FontFamily: '"Builder Sans"',
 *     FontWeight: '700',
 *     FontSize: 14,
 *     LineHeight: 1.2
 *   }}
 *   textColor="white"
 *   webTextElement="p"
 * />
 */
const WebText = ({ text, textFontStyle, textColor, webTextElement: WebTextElement = 'span' }) => {
    const { classes: { textClassName } } = useStyles({
        textFontStyle,
        textColor
    });
    const sanitizedText = React.useMemo(() => domPurify.sanitize(text, DOM_PURIFY_CONFIG), [text]);
    return (React.createElement(WebTextElement, { className: textClassName, ...getTextDataAttribute(defaultTextDataAttributeConfig), 
        // eslint-disable-next-line react/no-danger
        dangerouslySetInnerHTML: { __html: sanitizedText } }));
};

export { WebText as default };
